INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (190, 1, '지금 쓰는 컨텍스트 확인', 'kubectl 이 지금 어느 클러스터 설정(컨텍스트)을 쓰는지 한 줄로 보려면 어떻게 할까요? 컨텍스트 이름만 줄마다 나열하려면요?', 'config 아래에 current 와 get 으로 시작하는 하위 명령이 있어요.', NULL, NULL, '[]', 'choice', '["`kubectl get context` 로 현재 컨텍스트를 본다", "`kubectl cluster-info --current` 가 컨텍스트 이름을 출력한다", "`kubectl config current-context` 가 현재 컨텍스트 이름을 출력하고, `kubectl config get-contexts -o name` 이 컨텍스트 이름만 한 줄씩 나열한다", "`kubectl config show-context -o name` 이 이름을 나열한다"]', 2, '컨텍스트는 클러스터, 사용자, 기본 네임스페이스를 묶은 이름입니다.', NULL, NULL, NULL, NULL),
  (190, 2, '기본 네임스페이스 바꾸기', '`kubectl config set-context --current --namespace=작업ns` 를 하면 이후 `kubectl get deploy` 는 어느 네임스페이스를 조회할까요? 현재 설정된 네임스페이스는 어떻게 볼까요?', '-n 을 매번 쓰지 않아도 돼요.', NULL, NULL, '[]', 'choice', '["`default` 네임스페이스만 조회한다", "현재 컨텍스트의 기본 네임스페이스가 `작업ns` 로 바뀌어 `-n` 없이도 그곳을 조회한다. `kubectl config view --minify -o jsonpath=''{..namespace}''` 로 현재 값을 볼 수 있다", "모든 네임스페이스를 조회한다", "설정은 명령을 실행한 터미널 창에만 적용되고 파일에는 저장되지 않는다"]', 1, '`--namespace=` 처럼 값을 비우면 다시 기본값(`default`)으로 돌아갑니다.', NULL, NULL, NULL, NULL),
  (190, 3, '--context 와 use-context', '`kubectl --context=tmpctx config view --minify -o jsonpath=''{..namespace}''` 와 `kubectl config use-context tmpctx` 는 각각 현재 컨텍스트를 바꿀까요?', '하나는 한 번만, 하나는 계속 바뀌어요.', NULL, NULL, '[]', 'choice', '["`--context=tmpctx` 는 그 명령 한 번에만 적용되고 저장된 현재 컨텍스트는 바뀌지 않는다. `use-context tmpctx` 는 `Switched to context` 메시지와 함께 현재 컨텍스트를 바꾸고 설정 파일에 저장한다", "둘 다 한 번만 적용되고 저장되지 않는다", "`--context` 는 설정 파일의 현재 컨텍스트를 바꾼다", "`use-context` 는 그 터미널 창에서만 유효하다"]', 0, '`kubectl config delete-context 이름` 은 컨텍스트 항목을 설정 파일에서 지웁니다.', NULL, NULL, NULL, NULL),
  (190, 4, 'config view 의 인증서', '`kubectl config view` 에서 클라이언트 인증서 같은 값은 어떻게 보일까요? 실제 값을 보려면요?', '기본은 가려서 보여 줘요.', NULL, NULL, '[]', 'choice', '["항상 실제 값이 그대로 출력된다", "`config view` 는 인증 정보를 전혀 보여 주지 않고 오류를 낸다", "`--raw` 를 쓰면 값이 `DATA+OMITTED` 로 바뀐다", "`DATA+OMITTED` 로 가려져 나온다. `kubectl config view --raw` 를 쓰면 인증서·키 데이터가 그대로 출력된다"]', 3, '`--raw` 의 출력은 민감한 값이므로 화면 공유나 로그에 남기지 않습니다.', NULL, NULL, NULL, NULL),
  (190, 5, '헤더 없이 출력', '`kubectl get pods --no-headers` 와 `-o custom-columns=NAME:.metadata.name,IMG:.spec.containers[0].image --no-headers` 는 무엇을 줄까요?', '첫 줄의 제목이 없어요.', NULL, NULL, '[]', 'choice', '["`--no-headers` 는 Pod 이름도 함께 빼고 출력한다", "`--no-headers` 는 `-o custom-columns` 와 함께 쓸 수 없다", "`--no-headers` 는 제목 줄을 빼고 데이터 줄만 출력한다 (Pod 한 줄이 5개 필드). `custom-columns` 는 지정한 경로로 열을 만들고 `--no-headers` 와 함께 쓰면 `busybox:1.36` 같은 값만 나온다", "Pod 한 줄은 항상 3개 필드이다"]', 2, '`custom-columns=A:.metadata.name` 처럼 쓰면 제목이 `A` 로 나옵니다.', NULL, NULL, NULL, NULL),
  (190, 6, 'jsonpath 에서 없는 필드', '`kubectl get deploy web -o jsonpath=''{.nonexist}''` 는 어떻게 될까요? `{.metadata.labels}` 는요?', '없는 필드는 오류가 아니라 빈 출력이에요.', NULL, NULL, '[]', 'choice', '["`error: nonexist is not found` 로 실패한다", "없는 필드는 아무것도 출력하지 않고 오류 없이 종료 코드 0 으로 끝난다. `{.metadata.labels}` 는 맵 전체를 `{\\"app\\":\\"web\\",\\"tier\\":\\"fe\\"}` 처럼 JSON 으로 출력한다", "`{.metadata.labels}` 는 `app` 의 값만 출력한다", "없는 필드는 `null` 문자열을 출력한다"]', 1, '개수를 세려면 `{range .items[*]}{.metadata.name}{"\\n"}{end}` 처럼 줄마다 출력한 뒤 `wc -l` 로 셉니다.', NULL, NULL, NULL, NULL),
  (190, 7, '라벨 셀렉터 식', '라벨이 `app=web,tier=fe` 인 Deployment 에 대해 `-l tier=fe,app=web`, `-l ''tier in (fe,be)''`, `-l ''!nolabel''`, `-l ''tier notin (fe)''` 는 각각 이 Deployment 를 조회할까요?', '쉼표는 "그리고", 느낌표는 "없음"이에요.', NULL, NULL, '[]', 'choice', '["앞의 세 개는 조회하고 `tier notin (fe)` 는 `tier` 가 `fe` 인 것을 제외하므로 조회하지 않는다. 쉼표로 이은 조건은 모두 맞아야 하고(AND), `!키` 는 그 라벨이 없는 것을 고른다", "`-l ''tier in (fe,be)''` 는 둘 다 있어야 해서 조회하지 않는다", "`-l ''!nolabel''` 은 문법 오류이다", "`-l tier=fe,app=web` 은 둘 중 하나만 맞아도 조회한다"]', 0, '셀렉터는 `kubectl get` 뿐 아니라 `delete`, `label` 등에도 같은 문법으로 쓸 수 있습니다.', NULL, NULL, NULL, NULL),
  (190, 8, 'get all 과 여러 종류', '`kubectl get all -o name` 에는 ConfigMap 이 나올까요? `kubectl get cm,deploy -o name` 은 이름을 어떤 모양으로 보여 줄까요?', 'all 은 모든 종류가 아니에요.', NULL, NULL, '[]', 'choice', '["`get all` 에 ConfigMap 도 모두 나온다", "`-o name` 은 이름만 출력하고 종류는 붙이지 않는다", "쉼표로 여러 종류를 한 번에 조회할 수 없다", "`get all` 에는 Pod, ReplicaSet, Deployment 등이 나오지만 ConfigMap 은 나오지 않는다. `get cm,deploy -o name` 은 `configmap/cm1`, `deployment.apps/web` 처럼 `종류/이름` 모양으로 보여 준다"]', 3, '`종류/이름` 모양은 `kubectl delete` 나 `describe` 의 인자로 그대로 쓸 수 있습니다.', NULL, NULL, NULL, NULL),
  (190, 9, 'field-selector', '`--field-selector=status.phase=Running` 은 어떤 일을 할까요? `--field-selector=spec.replicas=3` 을 Deployment 에 쓰면요?', '필드 셀렉터는 지원하는 필드가 정해져 있어요.', NULL, NULL, '[]', 'choice', '["`spec.replicas=3` 도 Deployment 에서 정상 동작한다", "필드 셀렉터는 라벨만 걸러 낼 수 있다", "`status.phase=Running` 은 실행 중인 Pod 만 걸러 낸다(해당이 없으면 `No resources found`). Deployment 에 `spec.replicas=3` 을 쓰면 지원하지 않는 필드라 `is not a known field selector` 오류가 나고 `metadata.name`, `metadata.namespace` 만 허용된다고 알려 준다", "해당 Pod 가 없으면 오류와 종료 코드 1 로 끝난다"]', 2, '조건이 맞는 항목이 없을 때는 `No resources found in 네임스페이스 namespace.` 만 출력됩니다.', NULL, NULL, NULL, NULL),
  (190, 10, 'api-resources 와 api-versions', '`kubectl api-resources --namespaced=false -o name` 과 `kubectl api-resources --api-group=apps -o name` 은 각각 무엇을 보여 줄까요? `kubectl api-versions` 에는 어떤 값이 있을까요?', '네임스페이스에 속하지 않는 리소스와 그룹별 목록이에요.', NULL, NULL, '[]', 'choice', '["앞은 `pods` 같은 네임스페이스 리소스를 보여 준다", "앞은 `namespaces`, `nodes` 같은 네임스페이스에 속하지 않는 리소스, 뒤는 `deployments.apps`, `replicasets.apps`, `statefulsets.apps` 같은 apps 그룹 리소스를 보여 준다. `api-versions` 에는 `v1`, `apps/v1` 같은 그룹/버전 값이 있다", "`api-versions` 는 리소스 이름 목록을 출력한다", "`--api-group=apps` 는 `v1` 그룹의 리소스를 보여 준다"]', 1, '`kubectl api-resources` 의 열은 `NAME`, `SHORTNAMES`, `APIVERSION`, `NAMESPACED`, `KIND` 입니다.', NULL, NULL, NULL, NULL),
  (190, 11, 'explain 으로 필드 찾기', '`kubectl explain deploy.spec.replicas` 와 `kubectl explain pod.spec.containers.image` 는 각각 무엇을 알려 줄까요?', '점으로 경로를 이어 써요.', NULL, NULL, '[]', 'choice', '["경로의 필드 설명을 보여 주고 처음에 `GROUP`(예: `apps`), `KIND`(예: `Deployment`), `VERSION`(예: `v1`) 같은 위치 정보를 보여 준다. `pod.spec.containers.image` 는 `KIND: Pod` 로 시작한다", "클러스터에 있는 실제 값을 보여 준다", "리소스를 만들어 보면서 필드를 설명한다", "점으로 이은 경로는 지원하지 않는다"]', 0, '필드의 위치와 형식을 알고 싶을 때 `explain`, 실제 값을 볼 때는 `get -o yaml` 을 씁니다.', NULL, NULL, NULL, NULL),
  (190, 12, '없는 리소스 삭제', '`kubectl delete pod nonexist` 는 어떻게 끝날까요? `--ignore-not-found` 를 붙이면요?', '스크립트에서 오류를 피할 때 써요.', NULL, NULL, '[]', 'choice', '["기본으로도 오류 없이 종료 코드 0 이다", "`--ignore-not-found` 를 붙이면 같은 이름의 리소스를 새로 만든다", "`--ignore-not-found` 는 종료 코드 1 을 유지하고 메시지만 숨긴다", "`NotFound` 오류와 종료 코드 1 로 끝난다. `--ignore-not-found` 를 붙이면 오류 없이 종료 코드 0 으로 끝난다"]', 3, '`kubectl delete -l 라벨` 은 조건에 맞는 리소스를 모두 삭제합니다.', NULL, NULL, NULL, NULL),
  (190, 13, '--cascade=orphan', '`kubectl delete deploy web --cascade=orphan` 을 하면 Deployment 가 만든 Pod 는 어떻게 될까요?', '하위 리소스를 지우지 않는 옵션이에요.', NULL, NULL, '[]', 'choice', '["Pod 도 함께 즉시 삭제되어 `kubectl get pods` 에 아무것도 나오지 않는다", "Deployment 가 삭제되지 않는다", "Deployment 만 삭제되고 ReplicaSet 과 Pod 는 남는다 (삭제 뒤에도 Pod 가 그대로 조회되고 Pod 의 소유자는 ReplicaSet 으로 표시된다). 기본 삭제는 ReplicaSet 도 함께 지워 `No resources found` 가 된다", "Pod 가 다른 Deployment 로 자동으로 옮겨 간다"]', 2, '남은 ReplicaSet 은 `kubectl get rs` 로 확인하고 직접 지워야 합니다.', NULL, NULL, NULL, NULL),
  (190, 14, 'delete 의 dry-run', '`kubectl delete cm/cc1 --dry-run=client` 를 하면 어떻게 될까요? 없는 `ghost` 에 `--dry-run=server` 를 쓰면요?', '실제로 지우지는 않아요.', NULL, NULL, '[]', 'choice', '["`--dry-run=client` 도 실제로 삭제한다", "`configmap \\"cc1\\" deleted ... (dry run)` 이라고 출력하지만 ConfigMap 은 그대로 남는다. `--dry-run=server` 는 서버에서 확인하므로 없는 `ghost` 는 `NotFound` 오류가 난다", "`--dry-run=server` 는 없는 리소스도 성공으로 출력한다", "`--dry-run` 은 `delete` 에서는 쓸 수 없다"]', 1, '`--dry-run=client` 는 서버에 있는지는 확인하지 않고 지정한 대상만 보여 줍니다.', NULL, NULL, NULL, NULL),
  (190, 15, '현재 컨텍스트', '현재 컨텍스트 이름을 출력하는 `config` 하위 명령을 채우세요.', '"현재"와 "컨텍스트"를 이은 이름이에요.', NULL, NULL, '[]', 'fill', '["current-context", "get-current", "show-context", "whoami"]', NULL, '컨텍스트 이름만 나열하려면 `get-contexts -o name` 을 씁니다.', '[0]', 'kubectl config {0}', NULL, NULL),
  (190, 16, '컨텍스트 바꾸기', '다른 컨텍스트로 전환하는 `config` 하위 명령을 채우세요.', '"컨텍스트를 사용하라"는 뜻이에요.', NULL, NULL, '[]', 'fill', '["use-context", "set-context", "switch", "select-context"]', NULL, '`Switched to context "tmpctx"` 메시지가 나옵니다.', '[0]', 'kubectl config {0} tmpctx', NULL, NULL),
  (190, 17, '기본 네임스페이스 지정', '현재 컨텍스트의 기본 네임스페이스를 `dev` 로 바꾸는 옵션을 채우세요.', '`set-context --current` 뒤에 써요.', NULL, NULL, '[]', 'fill', '["--namespace", "--ns", "--default-ns", "--project"]', NULL, '그 뒤로는 `-n` 없이도 `dev` 를 조회합니다.', '[0]', 'kubectl config set-context --current {0}=dev', NULL, NULL),
  (190, 18, '제목 줄 빼기', '`kubectl get pods` 출력에서 제목 줄을 빼는 옵션을 채우세요.', '"헤더 없음"이라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--no-headers", "--no-title", "--skip-header", "-q"]', NULL, '`awk` 로 열을 뽑거나 `wc -l` 로 개수를 셀 때 유용합니다.', '[0]', 'kubectl get pods {0}', NULL, NULL),
  (190, 19, '이름만 출력', '리소스를 `종류/이름` 형태로만 출력하는 출력 형식을 채우세요.', '-o 뒤에 쓰며 "이름"이라는 뜻의 단어예요.', NULL, NULL, '[]', 'fill', '["name", "short", "id", "names"]', NULL, '예: `configmap/cm1`, `deployment.apps/web`.', '[0]', 'kubectl get cm -o {0}', NULL, NULL),
  (190, 20, '필드 셀렉터 옵션', '`status.phase=Running` 인 Pod 만 조회하는 옵션을 채우세요.', '"필드 선택"이라는 뜻의 긴 옵션이에요.', NULL, NULL, '[]', 'fill', '["--field-selector", "--selector", "--where", "--filter"]', NULL, '지원하는 필드는 리소스마다 정해져 있습니다.', '[0]', 'kubectl get pods {0}=status.phase=Running', NULL, NULL),
  (190, 21, '라벨 없는 것 고르기', '`nolabel` 라벨이 없는 리소스를 고르는 셀렉터를 채우세요.', '라벨 이름 앞에 느낌표를 붙여요.', NULL, NULL, '[]', 'fill', '["!", "-", "~", "^"]', NULL, '`tier notin (fe)` 처럼 집합 조건도 쓸 수 있습니다.', '[0]', 'kubectl get deploy -l ''{0}nolabel''', NULL, NULL),
  (190, 22, '네임스페이스 밖 리소스', '네임스페이스에 속하지 않는 리소스만 나열하도록 `api-resources` 에 붙이는 옵션을 채우세요.', '값은 `false` 로 줘요.', NULL, NULL, '[]', 'fill', '["--namespaced", "--cluster", "--global", "--scoped"]', NULL, '`namespaces`, `nodes` 같은 리소스가 나옵니다.', '[0]', 'kubectl api-resources {0}=false', NULL, NULL),
  (190, 23, '없어도 오류 내지 않기', '삭제할 대상이 없어도 오류 없이 끝나게 하는 옵션을 채우세요.', '"없음을 무시"라는 뜻의 긴 옵션이에요.', NULL, NULL, '[]', 'fill', '["--ignore-not-found", "--force", "--quiet", "--skip-missing"]', NULL, '옵션이 없으면 `NotFound` 오류와 종료 코드 1 입니다.', '[0]', 'kubectl delete pod nonexist {0}', NULL, NULL),
  (190, 24, '하위 리소스 남기기', 'Deployment 만 지우고 Pod 는 남기는 `--cascade` 값을 채우세요.', '"고아"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["orphan", "none", "keep", "skip"]', NULL, '기본 삭제는 ReplicaSet 도 함께 지웁니다.', '[0]', 'kubectl delete deploy web --cascade={0}', NULL, NULL),
  (190, 25, '삭제 흉내만 내기', '삭제하지 않고 `(dry run)` 으로 보여 주기만 하는 옵션 값을 채우세요.', '클라이언트에서만 처리해요.', NULL, NULL, '[]', 'fill', '["client", "local", "preview", "plan"]', NULL, '서버에서 확인하려면 `server` 를 씁니다.', '[0]', 'kubectl delete cm/cc1 --dry-run={0}', NULL, NULL),
  (190, 26, '작업 네임스페이스로 바꿔 작업하기', '기본 네임스페이스를 바꿔 작업하고 되돌리는 순서입니다. 순서에 맞게 놓아 보세요.', '확인 → 변경 → 조회 → 되돌리기 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl config current-context` 로 지금 컨텍스트를 확인한다", "`kubectl config set-context --current --namespace=작업ns` 로 기본 네임스페이스를 바꾼다", "`kubectl get deploy` 를 `-n` 없이 실행해 작업ns 의 것이 나오는지 본다", "`kubectl config set-context --current --namespace=` 로 기본값으로 되돌린다"]', NULL, '`kubectl config view --minify -o jsonpath=''{..namespace}''` 로 현재 값을 확인할 수 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (190, 27, '원하는 필드만 뽑아 쓰기', 'Deployment 의 복제본 수를 스크립트에서 쓰기 위해 뽑는 순서입니다. 순서에 맞게 놓아 보세요.', '전체 보기 → 경로 찾기 → 뽑기 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl get deploy web -o yaml` 로 전체 구조를 본다", "`.spec.replicas` 가 복제본 수 필드임을 확인한다", "`kubectl get deploy web -o jsonpath=''{.spec.replicas}''` 로 값만 출력한다", "출력이 `3` 처럼 한 값인지 확인한다"]', NULL, '없는 필드를 쓰면 오류 없이 빈 출력이 나오니 값이 비었는지 확인합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (190, 28, '라벨로 골라 안전하게 삭제하기', '라벨이 `grp=x` 인 ConfigMap 을 지우기 전에 확인하고 지우는 순서입니다. 순서에 맞게 놓아 보세요.', '미리 보기 → 대상 확인 → 삭제 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl delete cm -l grp=x --dry-run=client` 로 어떤 것이 지워질지 본다", "`kubectl get cm -l grp=x -o name` 으로 대상 이름을 확인한다", "`kubectl delete cm -l grp=x` 로 삭제한다", "`kubectl get cm -o name` 으로 남은 것을 확인한다"]', NULL, '`--all` 은 라벨과 상관없이 모두 지우므로 주의합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (190, 29, '리소스 종류에서 필드까지 찾기', '모르는 리소스의 필드를 찾아 읽는 순서입니다. 순서에 맞게 놓아 보세요.', '종류 찾기 → 필드 설명 → 값 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl api-resources` 로 리소스 이름과 그룹을 찾는다", "`kubectl api-versions` 로 그룹/버전 값을 확인한다", "`kubectl explain deploy.spec.replicas` 로 필드 설명을 읽는다", "`kubectl get deploy web -o yaml` 로 실제 값을 확인한다"]', NULL, '`explain` 은 필드 설명을, `get -o yaml` 은 실제 값을 보여 줍니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
